"""Start research turns through an operator-configured local host."""
import json
import os
from pathlib import Path
from queue import Empty, Full, Queue
import signal
import subprocess
from threading import Event, RLock, Thread
from time import monotonic, time

from rutile3.data.reference_research import digest
from rutile3.jobs.storage import read_json, write_json
from rutile3.services.reference_research import session_decision


HOSTS = {"pi", "codex"}
HOST_ENV = {"SYSTEMROOT", "WINDIR", "COMSPEC", "PATHEXT", "PATH", "TEMP", "TMP", "HOME", "USERPROFILE",
            "APPDATA", "LOCALAPPDATA", "LANG", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_RUNTIME_DIR"}


def research_task(request, staged=()):
    return (
        f"Research Rutile batch {request['request_id']} for project {request['project_id']}. "
        "Use get_reference_request to read the approved targets, saved evidence, and scratch directory. "
        "Follow the project research AGENTS.md. Use host-approved retrieval and the isolated offline Python runtime "
        "for extraction. Send a phase-data proposal or a specific unresolved finding for each target. "
        "Use the existing drafts if a target is already staged. "
        + (f"Already staged target IDs: {', '.join(staged)}." if staged else "")
    )


def host_command(host):
    config = os.environ.get(f"RUTILE_RESEARCH_{host.upper()}_COMMAND")
    if not config:
        raise ValueError("Configure a scoped launcher for the selected research host.")
    try:
        command = json.loads(config)
        if (not isinstance(command, list) or not command or not all(isinstance(part, str) for part in command)
                or not Path(command[0]).is_absolute() or not Path(command[0]).is_file()
                or Path(command[0]).suffix.lower() in {".ps1", ".bat", ".cmd"}):
            raise ValueError()
    except ValueError:
        raise ValueError("A research host command must be a JSON array beginning with an absolute executable path.") from None
    return command


def stop_process(process):
    if process.poll() is not None:
        return
    try:
        if os.name == "nt":
            subprocess.run(["taskkill", "/PID", str(process.pid), "/T", "/F"], capture_output=True, timeout=8,
                           creationflags=subprocess.CREATE_NO_WINDOW)
        else:
            os.killpg(process.pid, signal.SIGTERM)
        process.wait(timeout=5)
    except (OSError, subprocess.TimeoutExpired):
        if process.poll() is None:
            process.kill()
            process.wait(timeout=5)


class HostProcess:
    def __init__(self, command, folder, scratch):
        environment = {key: value for key, value in os.environ.items() if key.upper() in HOST_ENV}
        environment["RUTILE_RESEARCH_SCRATCH"] = str(scratch)
        self.process = subprocess.Popen(command, cwd=folder, env=environment, text=True, encoding="utf-8",
                                        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                                        start_new_session=os.name != "nt",
                                        creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0)
        self.messages = Queue(maxsize=512)
        self.stop_reading = Event()
        self.next_id = 0
        self.reader = Thread(target=self.read, daemon=True)
        self.reader.start()

    def read(self):
        try:
            for line in self.process.stdout:
                try:
                    value = json.loads(line)
                except ValueError:
                    continue
                while not self.stop_reading.is_set():
                    try:
                        self.messages.put(value, timeout=.25)
                        break
                    except Full:
                        pass
                if self.stop_reading.is_set():
                    return
        except (OSError, UnicodeError):
            return

    def send(self, message):
        self.process.stdin.write(json.dumps(message) + "\n")
        self.process.stdin.flush()

    def receive(self, until, timeout):
        deadline = monotonic() + timeout
        while monotonic() < deadline:
            try:
                message = self.messages.get(timeout=.25)
            except Empty:
                if self.process.poll() is not None:
                    break
                continue
            if isinstance(message, dict) and until(message):
                return message
        raise ValueError("The research host exited or timed out.")

    def rpc(self, *, method=None, params=None, type=None, **fields):
        self.next_id += 1
        identifier = self.next_id
        message = {"id": str(identifier), "type": type, **fields} if type else {
            "id": identifier, "method": method, "params": params or {}}
        self.send(message)
        response = self.receive(lambda value: value.get("id") == message["id"] and
                                (value.get("type") == "response" if type else "method" not in value), 30)
        if response.get("error") or response.get("success") is False:
            raise ValueError("The research host rejected the operation.")
        return response.get("data" if type else "result") or {}

    def close(self):
        self.stop_reading.set()
        stop_process(self.process)
        self.reader.join(timeout=2)
        self.process.stdin.close()
        self.process.stdout.close()


def launch_codex(client, folder, previous, task, save_session):
    client.rpc(method="initialize", params={"clientInfo": {"name": "rutile_research", "version": "1.0"}})
    client.send({"method": "initialized"})
    thread = None
    if previous:
        try:
            thread = client.rpc(method="thread/resume", params={"threadId": previous, "excludeTurns": True})["thread"]["id"]
        except ValueError:
            pass
    if not thread:
        thread = client.rpc(method="thread/start", params={"cwd": str(folder), "ephemeral": False})["thread"]["id"]
    save_session(thread, bool(previous and previous == thread))
    turn = client.rpc(method="turn/start", params={"threadId": thread, "input": [{"type": "text", "text": task,
                                                                                 "text_elements": []}]})["turn"]["id"]
    result = client.receive(lambda m: m.get("method") == "turn/completed"
                            and m.get("params", {}).get("turn", {}).get("id") == turn, 3600)
    return result["params"]["turn"]["status"] == "completed"


def launch_pi(client, previous, task, save_session):
    resumed = False
    if previous:
        try:
            resumed = not client.rpc(type="switch_session", sessionPath=previous).get("cancelled")
        except ValueError:
            pass
    if not resumed and client.rpc(type="new_session").get("cancelled"):
        raise ValueError("Pi canceled the research session.")
    if client.rpc(type="prompt", message=task).get("disposition") == "queued":
        raise ValueError("Pi queued the prompt behind another run.")
    result = client.receive(lambda m: m.get("type") == "agent_end", 3600)
    final = next((item for item in reversed(result.get("messages", [])) if item.get("role") == "assistant"), {})
    current = client.rpc(type="get_state")
    if current.get("sessionFile"):
        save_session(current["sessionFile"], resumed)
    return final.get("stopReason") == "stop"


class ResearchHosts:
    def __init__(self):
        self.lock = RLock()
        self.active = {}

    def available(self):
        return sorted(host for host in HOSTS if os.environ.get(f"RUTILE_RESEARCH_{host.upper()}_COMMAND"))

    def start(self, service, project_id, request_id, host):
        command = host_command(host)
        folder = service.store.project(project_id)
        # The configured launcher owns model credentials and the host permission profile.
        scope = os.environ.get(f"RUTILE_RESEARCH_{host.upper()}_SESSION_SCOPE", "")
        route = digest([host, command, scope])
        key = (project_id, route)
        path = folder / "sessions" / f"{route}.json"
        with self.lock:
            if request_id in self.active or any(run["key"] == key for run in self.active.values()):
                raise ValueError("A research batch is already running for this project and host.")
            service.reopen(project_id, request_id)
            request = service.status(project_id, request_id, agent=True)
            saved = read_json(path) if path.is_file() else {}
            decision = session_decision(request["session"], saved.get("ended_at"), time())
            previous = saved.get("session_id") if decision["action"] == "resume" else None
            run = {"key": key, "stop": Event(), "client": None}
            service.host_status(project_id, request_id, host, decision, running=True)
            self.active[request_id] = run
            thread = Thread(target=self.run, args=(service, request, host, command, folder, path, previous, decision, run),
                            daemon=True)
            run["thread"] = thread
            thread.start()
        return decision

    def run(self, service, request, host, command, folder, path, previous, decision, run):
        project_id, request_id = request["project_id"], request["request_id"]
        session_id = previous
        client = None
        state = "failed"
        error = None

        def save_session(identifier, resumed):
            nonlocal session_id
            session_id = identifier
            if previous and not resumed:
                service.host_status(project_id, request_id, host,
                                    {"action": "new", "reason": "Saved conversation could not be resumed"}, running=True)

        try:
            if not run["stop"].is_set():
                client = HostProcess(command, folder, Path(request["scratch_directory"]))
                with self.lock:
                    run["client"] = client
                if not run["stop"].is_set():
                    task = research_task(request, request["staged_targets"])
                    completed = (launch_codex(client, folder, previous, task, save_session) if host == "codex"
                                 else launch_pi(client, previous, task, save_session))
                    if completed:
                        # A completed conversation can still have gaps the user wishes to retry.
                        staged = service.status(project_id, request_id)["proposals"]
                        covered = {p["target_id"] for p in staged}
                        state = "completed" if request["targets"].keys() <= covered else "failed"
                        if state == "failed":
                            error = "The host ended before staging a finding for every target."
        except (OSError, ValueError, KeyError, TypeError):
            error = "The research host did not complete the run. Check its setup and review any staged drafts."
        finally:
            try:
                if client:
                    try:
                        client.close()
                    except OSError:
                        state, error = "failed", "The research host could not be closed cleanly."
                if session_id:
                    path.parent.mkdir(parents=True, exist_ok=True)
                    write_json(path, {"session_id": session_id, "ended_at": time()})
                if run["stop"].is_set():
                    state, error = "canceled", None
                service.host_status(project_id, request_id, host, None, running=False, error=error)
                service.finish(project_id, request_id, state)
            finally:
                with self.lock:
                    self.active.pop(request_id, None)

    def stop(self, request_id):
        with self.lock:
            run = self.active.get(request_id)
            if not run:
                return
            run["stop"].set()
            client = run["client"]
        if client:
            stop_process(client.process)

    def close(self):
        with self.lock:
            runs = list(self.active.items())
        for request_id, run in runs:
            self.stop(request_id)
            run["thread"].join(timeout=10)
"""Browser review and scoped local MCP access to reference research."""
from contextlib import contextmanager
from hmac import compare_digest
import os
from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, Query, Request
from fastapi.responses import FileResponse

from rutile3.data.materials_project import ReferenceUnavailable
from rutile3.domain.reference_research import Digest, LaunchResearch, MPLookup, NodeID, Proposal, ResearchRequest, Review, SessionEnd


@contextmanager
def research_errors():
    try:
        yield
    except FileNotFoundError:
        raise HTTPException(404, "The research batch, calculation, or referenced file is unavailable.") from None
    except ValueError as error:
        raise HTTPException(422, str(error)) from None


def browser_write(request: Request):
    if request.headers.get("authorization") or request.headers.get("origin") != str(request.base_url).rstrip("/"):
        raise HTTPException(403, "Open Rutile’s browser interface to change a research batch.")


def agent_access(request: Request):
    secret = os.environ.get("RUTILE_RESEARCH_TOKEN")
    scheme, _, supplied = request.headers.get("authorization", "").partition(" ")
    if (scheme != "Bearer" or not secret or len(secret) < 32 or not supplied.isascii()
            or not compare_digest(secret.encode("utf-8"), supplied.encode("ascii"))):
        raise HTTPException(401, "Configure the Rutile research connector credential.")


def research_router(service, hosts, api_key):
    router = APIRouter(prefix="/api/reference-research")
    browser = [Depends(browser_write)]
    agent = [Depends(agent_access)]

    @router.get("/hosts")
    def available_hosts():
        return {"hosts": hosts.available(), "connector_configured": len(os.environ.get("RUTILE_RESEARCH_TOKEN", "")) >= 32}

    @router.post("/requests", status_code=201, dependencies=browser)
    def create(body: ResearchRequest):
        with research_errors():
            return service().create(body)

    @router.get("/requests/{project_id}")
    def history(project_id: UUID, assignment_node: NodeID):
        with research_errors():
            return {"batches": service().store.history(str(project_id), assignment_node)}

    @router.get("/requests/{project_id}/{request_id}")
    def status(project_id: UUID, request_id: UUID):
        with research_errors():
            return service().status(str(project_id), str(request_id))

    @router.get("/requests/{project_id}/{request_id}/artifacts/{proposal_id}/{sha256}")
    def artifact(project_id: UUID, request_id: UUID, proposal_id: Digest, sha256: Digest):
        with research_errors():
            path, filename = service().store.artifact(str(project_id), str(request_id), proposal_id, sha256)
            return FileResponse(path, media_type="application/octet-stream", filename=filename)

    @router.post("/requests/{project_id}/{request_id}/review", dependencies=browser)
    def review(project_id: UUID, request_id: UUID, body: Review):
        with research_errors():
            return service().review(str(project_id), str(request_id), body)

    @router.post("/requests/{project_id}/{request_id}/finish", dependencies=browser)
    def finish(project_id: UUID, request_id: UUID, body: SessionEnd):
        with research_errors():
            hosts.stop(str(request_id))
            return service().finish(str(project_id), str(request_id), body.state)

    @router.post("/requests/{project_id}/{request_id}/launch", status_code=202, dependencies=browser)
    def launch(project_id: UUID, request_id: UUID, body: LaunchResearch):
        if len(os.environ.get("RUTILE_RESEARCH_TOKEN", "")) < 32:
            raise HTTPException(422, "Configure the local MCP connector before launching a research host.")
        with research_errors():
            return hosts.start(service(), str(project_id), str(request_id), body.host)

    @router.get("/agent/{project_id}/{request_id}", dependencies=agent)
    def context(project_id: UUID, request_id: UUID, restore: Annotated[list[Digest] | None, Query(max_length=8)] = None):
        with research_errors():
            return service().status(str(project_id), str(request_id), agent=True, restore=restore or ())

    @router.post("/agent/{project_id}/{request_id}/materials", dependencies=agent)
    def materials(project_id: UUID, request_id: UUID, body: MPLookup):
        with research_errors():
            try:
                return service().materials(str(project_id), str(request_id), body, api_key())
            except ReferenceUnavailable as error:
                return {"state": "unavailable", "reason": str(error)}

    @router.post("/agent/{project_id}/{request_id}/proposal", dependencies=agent)
    def stage(project_id: UUID, request_id: UUID, body: Proposal):
        with research_errors():
            return service().stage(str(project_id), str(request_id), body)

    return router

