"""Browser review and scoped local MCP access to reference research."""
from contextlib import contextmanager
from hmac import compare_digest
import os
from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, Query, Request
from fastapi.responses import FileResponse

from rutile3.data.materials_project import ReferenceUnavailable
from rutile3.domain.reference_research import Digest, LaunchResearch, MPLookup, NodeID, Proposal, ResearchRequest, Review, SessionEnd


@contextmanager
def research_errors():
    try:
        yield
    except FileNotFoundError:
        raise HTTPException(404, "The research batch, calculation, or referenced file is unavailable.") from None
    except ValueError as error:
        raise HTTPException(422, str(error)) from None


def browser_write(request: Request):
    if request.headers.get("authorization") or request.headers.get("origin") != str(request.base_url).rstrip("/"):
        raise HTTPException(403, "Open Rutile’s browser interface to change a research batch.")


def agent_access(request: Request):
    secret = os.environ.get("RUTILE_RESEARCH_TOKEN")
    scheme, _, supplied = request.headers.get("authorization", "").partition(" ")
    if (scheme != "Bearer" or not secret or len(secret) < 32 or not supplied.isascii()
            or not compare_digest(secret.encode("utf-8"), supplied.encode("ascii"))):
        raise HTTPException(401, "Configure the Rutile research connector credential.")


def research_router(service, hosts, api_key):
    router = APIRouter(prefix="/api/reference-research")
    browser = [Depends(browser_write)]
    agent = [Depends(agent_access)]

    @router.get("/hosts")
    def available_hosts():
        return {"hosts": hosts.available(), "connector_configured": len(os.environ.get("RUTILE_RESEARCH_TOKEN", "")) >= 32}

    @router.post("/requests", status_code=201, dependencies=browser)
    def create(body: ResearchRequest):
        with research_errors():
            return service().create(body)

    @router.get("/requests/{project_id}")
    def history(project_id: UUID, assignment_node: NodeID):
        with research_errors():
            return {"batches": service().store.history(str(project_id), assignment_node)}

    @router.get("/requests/{project_id}/{request_id}")
    def status(project_id: UUID, request_id: UUID):
        with research_errors():
            return service().status(str(project_id), str(request_id))

    @router.get("/requests/{project_id}/{request_id}/artifacts/{proposal_id}/{sha256}")
    def artifact(project_id: UUID, request_id: UUID, proposal_id: Digest, sha256: Digest):
        with research_errors():
            path, filename = service().store.artifact(str(project_id), str(request_id), proposal_id, sha256)
            return FileResponse(path, media_type="application/octet-stream", filename=filename)

    @router.post("/requests/{project_id}/{request_id}/review", dependencies=browser)
    def review(project_id: UUID, request_id: UUID, body: Review):
        with research_errors():
            return service().review(str(project_id), str(request_id), body)

    @router.post("/requests/{project_id}/{request_id}/finish", dependencies=browser)
    def finish(project_id: UUID, request_id: UUID, body: SessionEnd):
        with research_errors():
            hosts.stop(str(request_id))
            return service().finish(str(project_id), str(request_id), body.state)

    @router.post("/requests/{project_id}/{request_id}/launch", status_code=202, dependencies=browser)
    def launch(project_id: UUID, request_id: UUID, body: LaunchResearch):
        if len(os.environ.get("RUTILE_RESEARCH_TOKEN", "")) < 32:
            raise HTTPException(422, "Configure the local MCP connector before launching a research host.")
        with research_errors():
            return hosts.start(service(), str(project_id), str(request_id), body.host)

    @router.get("/agent/{project_id}/{request_id}", dependencies=agent)
    def context(project_id: UUID, request_id: UUID, restore: Annotated[list[Digest] | None, Query(max_length=8)] = None):
        with research_errors():
            return service().status(str(project_id), str(request_id), agent=True, restore=restore or ())

    @router.post("/agent/{project_id}/{request_id}/materials", dependencies=agent)
    def materials(project_id: UUID, request_id: UUID, body: MPLookup):
        with research_errors():
            try:
                return service().materials(str(project_id), str(request_id), body, api_key())
            except ReferenceUnavailable as error:
                return {"state": "unavailable", "reason": str(error)}

    @router.post("/agent/{project_id}/{request_id}/proposal", dependencies=agent)
    def stage(project_id: UUID, request_id: UUID, body: Proposal):
        with research_errors():
            return service().stage(str(project_id), str(request_id), body)

    return router
"""Opt-in stdio MCP bridge for the local Alloy Studio reference service."""
import os
from urllib.parse import urlsplit
from uuid import UUID

import requests

from rutile3.domain.reference_research import Digest, MaterialID, MPLookup, Proposal


def server():
    try:
        from mcp.server.fastmcp import FastMCP
    except ImportError:
        raise SystemExit("Install Rutile’s optional agent dependencies to start the MCP bridge.") from None

    url = urlsplit(os.environ.get("RUTILE_RESEARCH_URL", "http://127.0.0.1:8000"))
    if (url.scheme != "http" or url.hostname not in {"127.0.0.1", "localhost", "::1"}
            or url.username or url.password or url.path not in {"", "/"} or url.query or url.fragment):
        raise SystemExit("RUTILE_RESEARCH_URL must name the local Rutile HTTP server.")
    key = os.environ.get("RUTILE_RESEARCH_TOKEN")
    if not key or len(key) < 32 or not key.isascii():
        raise SystemExit("Configure the same RUTILE_RESEARCH_TOKEN on Rutile and the MCP bridge.")

    mcp = FastMCP("Rutile reference research")

    def call(method, project, request, action="", **kwargs):
        endpoint = f"{url.scheme}://{url.netloc}/api/reference-research/agent/{project}/{request}{action}"
        try:
            with requests.Session() as client:
                client.trust_env = False
                response = client.request(method, endpoint, headers={"Authorization": f"Bearer {key}"},
                                          timeout=(3, 60), allow_redirects=False, **kwargs)
            body = response.json()
        except (requests.RequestException, ValueError):
            raise ValueError("The Rutile reference service is unavailable. Check that the local app is running.") from None
        if not response.ok or response.is_redirect:
            detail = body.get("detail")
            if isinstance(detail, list):
                detail = "; ".join(f"{'.'.join(map(str, issue['loc'][1:]))}: {issue['msg']}" for issue in detail)
            raise ValueError(detail or "Rutile rejected the research request.")
        return body

    @mcp.tool()
    def get_reference_request(project_id: UUID, request_id: UUID, restore_artifacts: list[Digest] | None = None) -> dict:
        """Read the approved batch, target IDs, scratch folder, and saved evidence. Pass up to eight saved SHA-256 IDs to copy those files into scratch."""
        if restore_artifacts and len(restore_artifacts) > 8:
            raise ValueError("Restore at most eight saved files per call.")
        return call("GET", project_id, request_id, params={"restore": restore_artifacts or []})

    @mcp.tool()
    def search_materials_project(project_id: UUID, request_id: UUID, target_id: Digest,
                                 material_ids: list[MaterialID] | None = None) -> dict:
        """Look up the selected phase chemistry or specific MP IDs using Rutile’s configured backend key."""
        query = MPLookup(target_id=target_id, material_ids=material_ids or [])
        return call("POST", project_id, request_id, "/materials", json=query.model_dump(mode="json"))

    @mcp.tool()
    def stage_phase_data_proposal(project_id: UUID, request_id: UUID, proposal: Proposal) -> dict:
        """Save one candidate or unresolved finding for Inspector review. For a model result, the JSON output must contain a values object matching the submitted numbers and units."""
        return call("POST", project_id, request_id, "/proposal", json=proposal.model_dump(mode="json"))

    return mcp


if __name__ == "__main__":
    server().run()

