class ReferenceResearch:
    def __init__(self, jobs, catalog):
        self.jobs = jobs
        self.catalog = catalog
        self.store = ResearchStore(catalog.workspace)
        self.lock = RLock()

    def phase_set(self, job):
        _, _, result, _ = completed_equilibrium(self.jobs, job)
        return result.get("phase_set") or equilibrium_phase_set(result, job)

    def create(self, body):
        job = str(body.equilibrium_job)
        phase_set = self.phase_set(job)
        assignment_job = str(body.assignment_job)
        directory = self.jobs.folder(assignment_job)
        saved = read_json(directory / "request.json")
        if (saved["kind"] != "workflow_assignment" or saved["selection"].get("equilibrium_job") != job
                or self.jobs.status(assignment_job)["state"] != "completed"):
            raise ValueError("Run Phase Assignment for the current equilibrium before researching the gaps.")
        assigned = read_json(directory / "result.json")["phase_set"]["phases"]
        assigned = {phase["instance_id"]: phase for phase in assigned}
        phases = {phase["instance_id"]: phase for phase in phase_set["phases"]}
        targets = {}
        for item in body.targets:
            if item.phase_id not in phases or item.phase_id not in assigned:
                raise ValueError("A selected phase is absent from the saved assignment.")
            context = target_context(phases[item.phase_id], assigned[item.phase_id], phase_set, item.property)
            context["fingerprint"] = digest([job, phase_set["assessment_sha256"], context])
            targets[context["fingerprint"]] = context
        request = {**body.model_dump(mode="json", exclude={"targets"}), "schema_version": 1,
                   "request_id": str(uuid4()), "targets": targets, "state": "collecting", "created_at": time(),
                   "assessment_sha256": phase_set["assessment_sha256"]}
        with self.lock:
            self.store.create(request)
        return request

    def status(self, project_id, request_id, *, agent=False, restore=()):
        request = self.store.get(project_id, request_id)
        proposals = self.store.proposals(project_id, request_id)
        if agent:
            if request["state"] != "collecting" or not request["share_with_agent"]:
                raise ValueError("This research batch is closed.")
            folder = self.store.folder(project_id, request_id)
            saved = self.store.relevant(project_id, request["targets"].values())
            with self.lock:
                restored = self.store.restore_artifacts(request, saved, set(restore))
            return {**request, "scratch_directory": str(folder / "scratch"),
                    "instructions_file": str(self.store.project(project_id) / "AGENTS.md"),
                    "saved_research": saved, "restored_artifacts": restored,
                    "staged_targets": sorted({p["target"]["fingerprint"] for p in proposals})}
        return {**request, "proposals": proposals}

    def stage(self, project_id, request_id, submission):
        with self.lock:
            request = self.store.get(project_id, request_id)

    def finish(self, project_id, request_id, state):
        with self.lock:
            request = self.store.get(project_id, request_id)
            if request["state"] == "collecting":
                request.update(state=state, ended_at=time(), ended_at_utc=datetime.now(timezone.utc).isoformat())
                write_json(self.store.folder(project_id, request_id) / "request.json", request)
            return request

    def reopen(self, project_id, request_id):
        with self.lock:
            request = self.store.get(project_id, request_id)
            if request["state"] in {"failed", "canceled"}:
                request.update(state="collecting", ended_at=None, ended_at_utc=None)
                write_json(self.store.folder(project_id, request_id) / "request.json", request)

    def host_status(self, project_id, request_id, host, decision, *, running, error=None):
        with self.lock:
            request = self.store.get(project_id, request_id)
            updated = {"name": host, "running": running, "error": error,
                       "decision": decision or (request.get("host") or {}).get("decision")}
            request["host"] = updated
            write_json(self.store.folder(project_id, request_id) / "request.json", request)
import {createRutileScene} from './rutile-scene.js';
import {initOptimization} from './optimization.js';
import {initMaterialsSettings} from './materials-settings.js';
import {initMechanical} from './mechanical.js';
import {initAlloyStudio} from './alloy-studio.js';

const canvas = document.getElementById('rutile-scene');
const scene = createRutileScene(canvas, document.getElementById('gem-optics'));
const optimization = initOptimization(family => scene?.setAlloyFamily(family), step => scene?.setOptimizationStep(step));
const materialsSettings = initMaterialsSettings();
const mechanical = initMechanical();
const studio = initAlloyStudio(document.getElementById('studio-root'));
const sections = new Map([...document.querySelectorAll('.screen')].map(section =>
  [section.id.slice('screen-'.length), section]
));
const bar = document.getElementById('shell-bar');
const back = document.getElementById('shell-back');
const titleSettings = document.getElementById('title-settings');
const motion = document.getElementById('reduce-motion');
const motionPreference = matchMedia('(prefers-reduced-motion: reduce)');
const specimens = document.querySelectorAll('input[name="specimen"]');
const key = 'rutile.appearance';

let screen = 'title';
let returnScreen = 'menu';
let introTimer;
let drag;

function readPreferences() {
  try {
    const value = JSON.parse(localStorage.getItem(key));
    return {specimen: value?.specimen === 'lab' ? 'lab' : 'natural', reduce: value?.reduce === true};
  } catch {
    return {specimen: 'natural', reduce: false};
  }
}

const preferences = readPreferences();

function applyPreferences() {
  const reduce = preferences.reduce || motionPreference.matches;
  document.body.dataset.specimen = preferences.specimen;
  document.body.dataset.motion = reduce ? 'reduced' : 'full';
  scene?.setPreferences(preferences.specimen, reduce);
}

function savePreferences() {
  applyPreferences();
  try {
    localStorage.setItem(key, JSON.stringify(preferences));
  } catch {
    // Settings still apply to the open app when browser storage is unavailable.
  }
}

function show(next, moveFocus = true) {
  clearTimeout(introTimer);
  if (next === 'settings') returnScreen = screen;
  if (next === 'settings') materialsSettings.refresh();
  if (next === 'mechanical') mechanical.loadReferences();
  drag = undefined;
  screen = next;
  document.body.dataset.screen = next;
  document.body.toggleAttribute('data-intro-ready', next === 'loading');
  for (const [name, section] of sections) section.hidden = name !== next;
  if (next === 'studio') studio.mountBack(back);
  else if (back.parentElement !== bar) bar.prepend(back);
  bar.hidden = next === 'loading' || next === 'studio';
  back.hidden = next === 'title';
  titleSettings.hidden = next !== 'title';
  document.body.toggleAttribute('data-dive', scene?.setView(next === 'studio' ? 'diagrams' : next) === true);
  if (next === 'studio') studio.open();
  if (moveFocus) {
    window.scrollTo(0, 0);
    sections.get(next).querySelector('h1')?.focus({preventScroll: true});
  }
}

function goBack() {
  const previous = screen;
  if (previous === 'optimize' && optimization.previousStep()) return;
  if (previous === 'settings') {
    show(returnScreen, false);
    (returnScreen === 'title' ? titleSettings : document.getElementById('menu-settings')).focus();
  } else if (previous === 'optimize') {
    show('studio');
    document.querySelector(`#studio-root [data-alloy-mode="${optimization.mode}"]`)?.focus({preventScroll: true});
  } else if (previous === 'mechanical') {
    show('studio', false);
    window.scrollTo(0, 0);
    document.getElementById('studio-heading').focus({preventScroll: true});
  } else if (previous === 'diagrams' || previous === 'studio') {
    show('menu', false);
    window.scrollTo(0, 0);
    document.getElementById(previous === 'studio' ? 'menu-optimize' : `menu-${previous}`).focus({preventScroll: true});
  } else {
    show('title');
  }
}

for (const button of document.querySelectorAll('[data-open]')) {
  button.addEventListener('click', () => {
    if (button.dataset.alloyMode) optimization.setMode(button.dataset.alloyMode);
    show(button.dataset.open);
  });
